import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div
      data-slot="component-preview"
      className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-6 p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
    >
      {children}
    </div>
  );
}

import { Tabs, TabsList, TabsTrigger } from "@/registry/erbium/ui/tabs";

export function TabsDisabled() {
  return (
    <Tabs defaultValue="home">
      <TabsList>
        <TabsTrigger value="home">Home</TabsTrigger>
        <TabsTrigger value="settings" disabled>
          Disabled
        </TabsTrigger>
      </TabsList>
    </Tabs>
  );
}

import { HugeiconsIcon } from "@hugeicons/react";
import AppWindowIcon from "@hugeicons/core-free-icons/AppWindowIcon";
import CodeIcon from "@hugeicons/core-free-icons/CodeIcon";

import { Tabs, TabsList, TabsTrigger } from "@/registry/erbium/ui/tabs";

export function TabsIcons() {
  return (
    <Tabs defaultValue="preview">
      <TabsList>
        <TabsTrigger value="preview">
          <HugeiconsIcon icon={AppWindowIcon} />
          Preview
        </TabsTrigger>
        <TabsTrigger value="code">
          <HugeiconsIcon icon={CodeIcon} />
          Code
        </TabsTrigger>
      </TabsList>
    </Tabs>
  );
}

import { Tabs, TabsList, TabsTrigger } from "@/registry/erbium/ui/tabs";

export function TabsVertical() {
  return (
    <Tabs defaultValue="account" orientation="vertical">
      <TabsList>
        <TabsTrigger value="account">Account</TabsTrigger>
        <TabsTrigger value="password">Password</TabsTrigger>
        <TabsTrigger value="notifications">Notifications</TabsTrigger>
      </TabsList>
    </Tabs>
  );
}

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { Tabs } from "@/registry/erbium/ui/tabs";

import PlaygroundExample from "./variants/playground";

const PlaygroundSource = "import { Tabs, TabsList, TabsTrigger, TabsContent } from \"@/registry/erbium/ui/tabs\";\nimport type * as React from \"react\";\n\nconst Example = (args: React.ComponentProps<typeof Tabs>) => (\n  <Tabs key={args.defaultValue} {...args} className=\"w-72\">\n    <TabsList>\n      <TabsTrigger value=\"one\">First</TabsTrigger>\n      <TabsTrigger value=\"two\">Second</TabsTrigger>\n    </TabsList>\n    <TabsContent value=\"one\">First panel</TabsContent>\n    <TabsContent value=\"two\">Second panel</TabsContent>\n  </Tabs>\n);\n\nexport default Example;\n";

import OverviewExample from "./variants/overview";

const OverviewSource = "import Demo from \"../examples/tabs-demo\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <Demo />\n  </div>\n);\n\nexport default Example;\n";

import SelectionExample from "./variants/selection";

const SelectionSource = "import { Tabs, TabsList, TabsTrigger } from \"@/registry/erbium/ui/tabs\";\n\nconst Example = () => (\n  <Tabs defaultValue=\"overview\">\n    <TabsList>\n      <TabsTrigger value=\"overview\">Overview</TabsTrigger>\n      <TabsTrigger value=\"analytics\">Analytics</TabsTrigger>\n      <TabsTrigger value=\"reports\">Reports</TabsTrigger>\n    </TabsList>\n  </Tabs>\n);\n\nexport default Example;\n";

import VerticalExample from "./variants/vertical";

const VerticalSource = "import { TabsVertical } from \"../examples/tabs-vertical\";\n\nconst Example = () => <TabsVertical />;\n\nexport default Example;\n";

import DisabledExample from "./variants/disabled";

const DisabledSource = "import { TabsDisabled } from \"../examples/tabs-disabled\";\n\nconst Example = () => <TabsDisabled />;\n\nexport default Example;\n";

import IconsExample from "./variants/icons";

const IconsSource = "import { TabsIcons } from \"../examples/tabs-icons\";\n\nconst Example = () => <TabsIcons />;\n\nexport default Example;\n";

const meta = {
  component: Tabs,
  tags: ["autodocs"],
  parameters: {
    layout: "centered",
    docs: {
      description: {
        component: "## Usage\n\nDisplay one tab panel at a time, switching between related sections of content.\n\n**Import:** `@/registry/erbium/ui/tabs`\n\n## Usage\n\n```tsx\nimport { Tabs, TabsContent, TabsList, TabsTrigger } from \"@/registry/erbium/ui/tabs\";\n```\n\n```tsx\n<Tabs defaultValue=\"account\" className=\"w-[400px]\">\n  <TabsList>\n    <TabsTrigger value=\"account\">Account</TabsTrigger>\n    <TabsTrigger value=\"password\">Password</TabsTrigger>\n  </TabsList>\n  <TabsContent value=\"account\">Make changes to your account here.</TabsContent>\n  <TabsContent value=\"password\">Change your password here.</TabsContent>\n</Tabs>\n```\n\n## Composition\n\nUse the following composition to build `Tabs`:\n\n```text\nTabs\n├── TabsList\n│   ├── TabsTrigger\n│   └── TabsTrigger\n├── TabsContent\n└── TabsContent\n```\n\n## Base UI documentation\n\nExplore the underlying primitives and their API reference.\n\n- [Tabs](https://base-ui.com/react/components/tabs)",
      },
    },
  },
} satisfies Meta<typeof Tabs>;

export default { ...meta, title: "Navigation/Tabs",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<typeof Tabs> = {
  args: { defaultValue: "one", orientation: "horizontal" },
  argTypes: {
    defaultValue: { control: "select", options: ["one", "two"] },
    orientation: { control: "select", options: ["horizontal", "vertical"] },
  },
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: PlaygroundSource },
    },
  },
  render: PlaygroundExample,
};

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: OverviewSource },
    },
  },
  render: OverviewExample,
};

export const Selection: Story = {
  parameters: {
    docs: {
      description: { story: "The raised selection moves across the recessed tab list." },
      source: { code: SelectionSource },
    },
  },
  render: SelectionExample,
};

export const Vertical: Story = {
  parameters: {
    docs: {
      description: { story: "Use `orientation=\"vertical\"` for vertical tabs." },
      source: { code: VerticalSource },
    },
  },
  render: VerticalExample,
};

export const Disabled: Story = {
  parameters: {
    docs: {
      description: { story: "Disable a tab that is not available." },
      source: { code: DisabledSource },
    },
  },
  render: DisabledExample,
};

export const Icons: Story = {
  parameters: {
    docs: {
      description: { story: "Add icons to tab triggers." },
      source: { code: IconsSource },
    },
  },
  render: IconsExample,
};

